import React, { useEffect, useRef, useState } from "react";
import { Html5Qrcode } from "html5-qrcode";

function QRScanner() {

  const scannerRef = useRef(null);
  const lastScan = useRef(null);

  const [student, setStudent] = useState(null);
  const [status, setStatus] = useState("");

  useEffect(() => {

    const startScanner = async () => {

      try {

        const scanner = new Html5Qrcode("reader");
        scannerRef.current = scanner;

        const cameras = await Html5Qrcode.getCameras();

        if (cameras.length > 0) {

          const cameraId = cameras[0].id;

          await scanner.start(
            cameraId,
            {
              fps: 10,
              qrbox: 250
            },

            async (decodedText) => {

              if (lastScan.current === decodedText) return;
              lastScan.current = decodedText;

              console.log("QR:", decodedText);

              try {

                const verify = await fetch(
                  `http://localhost:5000/verify-user/${decodedText}`
                );

                const verifyData = await verify.json();

                if (!verifyData.success) {

                  setStatus("notfound");
                  setStudent(null);

                  setTimeout(() => {
                    lastScan.current = null;
                  }, 2000);

                  return;
                }

                setStudent(verifyData.user);

                const attendance = await fetch(
                  `http://localhost:5000/mark-attendance/${decodedText}`,
                  {
                    method: "PUT"
                  }
                );

                const attendanceData = await attendance.json();

                if (attendanceData.success) {

                  setStatus("success");

                } else {

                  setStatus("already");

                }

              } catch (err) {

                console.log(err);
                setStatus("servererror");

              }

              setTimeout(() => {
                lastScan.current = null;
              }, 2000);

            }

          );

        }

      } catch (error) {

        console.log("Scanner error:", error);

      }

    };

    startScanner();

    return () => {

      if (scannerRef.current) {

        scannerRef.current
          .stop()
          .then(() => scannerRef.current.clear())
          .catch(() => {});

      }

    };

  }, []);

  return (

    <div style={{ textAlign: "center", marginTop: "40px" }}>

      <h2>QR Attendance Scanner</h2>

      <div
        id="reader"
        style={{
          width: "350px",
          height: "350px",
          margin: "auto",
          border: "3px solid black"
        }}
      ></div>

      {student && (

        <div
          style={{
            width: "320px",
            margin: "20px auto",
            padding: "20px",
            background: "#f5f5f5",
            borderRadius: "10px"
          }}
        >

          <h3>{student.name}</h3>
          <p>{student.college_name}</p>

          {status === "success" && (
            <h2 style={{ color: "green" }}>✔ Attendance Marked</h2>
          )}

          {status === "already" && (
            <h2 style={{ color: "red" }}>Already Scanned</h2>
          )}

          {status === "notfound" && (
            <h2 style={{ color: "orange" }}>User Not Found</h2>
          )}

        </div>

      )}

    </div>

  );
}

export default QRScanner;
